import { Annotation, END, START, StateGraph } from "@langchain/langgraph";

const State = Annotation.Root({
  message: Annotation(),
});
const graph = new StateGraph(State)
  .addNode("echo", () => ({ message: "langgraph-ready" }))
  .addEdge(START, "echo")
  .addEdge("echo", END)
  .compile();
const out = await graph.invoke({ message: "start" });
if (out.message !== "langgraph-ready") {
  throw new Error(`Unexpected state output: ${String(out.message)}`);
}
console.log(out.message);
